css:
/* From Uiverse.io by andrew-demchenk0 - Tags: login, email, social, form, submit, confirm, password, welcome */
.__UIV_SCOPE__ .form {
  --input-focus: #2d8cf0;
  --font-color: #323232;
  --font-color-sub: #666;
  --bg-color: #fff;
  --main-color: #323232;
  padding: 20px;
  background: lightgrey;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 20px;
  border-radius: 5px;
  border: 2px solid var(--main-color);
  box-shadow: 4px 4px var(--main-color);
}

.__UIV_SCOPE__ .title {
  color: var(--font-color);
  font-weight: 900;
  font-size: 20px;
  margin-bottom: 25px;
}

.__UIV_SCOPE__ .title span {
  color: var(--font-color-sub);
  font-weight: 600;
  font-size: 17px;
}

.__UIV_SCOPE__ .input {
  width: 250px;
  height: 40px;
  border-radius: 5px;
  border: 2px solid var(--main-color);
  background-color: var(--bg-color);
  box-shadow: 4px 4px var(--main-color);
  font-size: 15px;
  font-weight: 600;
  color: var(--font-color);
  padding: 5px 10px;
  outline: none;
}

.__UIV_SCOPE__ .input::placeholder {
  color: var(--font-color-sub);
  opacity: 0.8;
}

.__UIV_SCOPE__ .input:focus {
  border: 2px solid var(--input-focus);
}

.__UIV_SCOPE__ .login-with {
  display: flex;
  gap: 20px;
}

.__UIV_SCOPE__ .button-log {
  cursor: pointer;
  width: 40px;
  height: 40px;
  border-radius: 100%;
  border: 2px solid var(--main-color);
  background-color: var(--bg-color);
  box-shadow: 4px 4px var(--main-color);
  color: var(--font-color);
  font-size: 25px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .icon {
  width: 24px;
  height: 24px;
  fill: var(--main-color);
}

.__UIV_SCOPE__ .button-log:active, .__UIV_SCOPE__ .button-confirm:active {
  box-shadow: 0px 0px var(--main-color);
  transform: translate(3px, 3px);
}

.__UIV_SCOPE__ .button-confirm {
  margin: 50px auto 0 auto;
  width: 120px;
  height: 40px;
  border-radius: 5px;
  border: 2px solid var(--main-color);
  background-color: var(--bg-color);
  box-shadow: 4px 4px var(--main-color);
  font-size: 17px;
  font-weight: 600;
  color: var(--font-color);
  cursor: pointer;
}
